class MovingAverage:
    def __init__(self, size):
        self.size = size
        self.values = []

    def next(self, val):
        self.values.append(val)
        if len(self.values) > self.size:
            self.values.pop(0)                                            # O(n) shift to drop the oldest value
        return sum(self.values) / len(self.values)                        # O(n) rescan every single call


if __name__ == "__main__":
    ma = MovingAverage(3)
    print(ma.next(1))
    print(ma.next(10))
    print(ma.next(3))
    print(ma.next(5))

