import java.util.*;

public class Main {
    class MovingAverage {
        int size;
        List<Integer> values = new ArrayList<>();

        MovingAverage(int size) { this.size = size; }

        double next(int val) {
            values.add(val);
            if (values.size() > size) {
                values.remove(0);                                                     // O(n) shift to drop the oldest value
            }
            double sum = 0;
            for (int v : values) sum += v;                                              // O(n) rescan every single call
            return sum / values.size();
        }
    }

    public static void main(String[] args) {
        MovingAverage ma = new MovingAverage(3);
        System.out.println(ma.next(1));
        System.out.println(ma.next(10));
        System.out.println(ma.next(3));
        System.out.println(ma.next(5));
    }
}

