class MovingAverage {
public:
    int size;
    vector<int> values;

    MovingAverage(int size) : size(size) {}

    double next(int val) {
        values.push_back(val);
        if ((int)values.size() > size) {
            values.erase(values.begin());                                             // O(n) shift to drop the oldest value
        }
        double sum = 0;
        for (int v : values) sum += v;                                                  // O(n) rescan every single call
        return sum / values.size();
    }
};

