from collections import deque

class MovingAverage:
    def __init__(self, size):
        self.size = size
        self.queue = deque()                                                # holds only the last 'size' values
        self.running_sum = 0                                                # kept in sync incrementally, never recomputed from scratch

    def next(self, val):
        self.queue.append(val)
        self.running_sum += val
        if len(self.queue) > self.size:
            self.running_sum -= self.queue.popleft()                       # evict the oldest value, adjusting the sum in O(1)
        return self.running_sum / len(self.queue)


if __name__ == "__main__":
    ma = MovingAverage(3)
    print(ma.next(1))
    print(ma.next(10))
    print(ma.next(3))
    print(ma.next(5))

