import java.util.*;

public class Main {
    class MovingAverage {
        int size;
        Deque<Integer> queue = new ArrayDeque<>();                                    // holds only the last 'size' values
        double runningSum = 0;                                                          // kept in sync incrementally, never recomputed from scratch

        MovingAverage(int size) { this.size = size; }

        double next(int val) {
            queue.addLast(val);
            runningSum += val;
            if (queue.size() > size) {
                runningSum -= queue.pollFirst();                                            // evict the oldest value, adjusting the sum in O(1)
            }
            return runningSum / queue.size();
        }
    }

    public static void main(String[] args) {
        MovingAverage ma = new MovingAverage(3);
        System.out.println(ma.next(1));
        System.out.println(ma.next(10));
        System.out.println(ma.next(3));
        System.out.println(ma.next(5));
    }
}

